// Main-thread-only property — skip synchronization overhead
val expensiveRegex by lazy(LazyThreadSafetyMode.NONE) { Regex("...") }

// Shared across threads, occasional redundant init is acceptable
val sharedCache by lazy(LazyThreadSafetyMode.PUBLICATION) { buildCache() }

class CursorColumn<T>(private val cursor: Cursor, private val columnName: String, private val read: (Cursor, Int) -> T) : ReadOnlyProperty<Any?, T> {
    override fun getValue(thisRef: Any?, property: KProperty<*>): T =
        read(cursor, cursor.getColumnIndexOrThrow(columnName))
}

class UserRow(cursor: Cursor) {
    val name: String by CursorColumn(cursor, "name") { c, i -> c.getString(i) }
}

interface Repository<T> { fun getAll(): List<T> }

class CachingRepository<T>(
    private val delegate: Repository<T>
) : Repository<T> by delegate {
    private var cache: List<T>? = null
    override fun getAll(): List<T> = cache ?: delegate.getAll().also { cache = it }
}

class ValueDelegate<T>(private val value: T) : ReadOnlyProperty<Any?, T> {
    override fun getValue(thisRef: Any?, property: KProperty<*>) = value
    override fun equals(other: Any?) = other is ValueDelegate<*> && other.value == value
    override fun hashCode() = value?.hashCode() ?: 0
}

interface Greeter { fun greet(): String }

class LoudGreeter(g: Greeter) : Greeter by g
// compiles to a real override fun greet() = g.greet() under the hood — no reflection

interface A { fun name(): String }
interface B { fun name(): String }

class Combined(a: A, b: B) : A by a, B by b {
    override fun name(): String = a.name() // must resolve the conflict explicitly
}

class ThreadLocalDelegate<T>(private val initializer: () -> T) : ReadWriteProperty<Any?, T> {
    private val threadLocal = ThreadLocal.withInitial(initializer)
    override fun getValue(thisRef: Any?, property: KProperty<*>) = threadLocal.get()
    override fun setValue(thisRef: Any?, property: KProperty<*>, value: T) = threadLocal.set(value)
}

var requestContext: RequestContext by ThreadLocalDelegate { RequestContext() }

