class Validator {
    private val emailRegex by lazy {
        Regex("^[A-Za-z0-9+_.-]+@([A-Za-z0-9.-]+\\.[A-Za-z]{2,})$")
    }

    fun isValidEmail(input: String) = emailRegex.matches(input)
}

class RangeValidated(private val range: IntRange) : ReadWriteProperty<Any?, Int> {
    private var value = range.first
    override fun getValue(thisRef: Any?, property: KProperty<*>) = value
    override fun setValue(thisRef: Any?, property: KProperty<*>, value: Int) {
        require(value in range) { "Value must be in $range" }
        this.value = value
    }
}

class Settings { var volume by RangeValidated(0..100) }

interface Cache<K, V> { fun get(key: K): V?; fun put(key: K, value: V) }

class LoggingCache<K, V>(
    private val delegate: Cache<K, V>
) : Cache<K, V> by delegate {
    override fun put(key: K, value: V) {
        println("Caching $key")
        delegate.put(key, value)
    }
}

class UserConfig(private val map: Map<String, Any?>) {
    val name: String by map
    val age: Int by map
}

val config = UserConfig(mapOf("name" to "Ahmed", "age" to 30))
println(config.name) // "Ahmed"

class PrefDelegateProvider(private val prefs: SharedPreferences, private val default: String) {
    operator fun provideDelegate(thisRef: Any?, prop: KProperty<*>): ReadWriteProperty<Any?, String> =
        object : ReadWriteProperty<Any?, String> {
            override fun getValue(t: Any?, p: KProperty<*>) = prefs.getString(prop.name, default)!!
            override fun setValue(t: Any?, p: KProperty<*>, v: String) = prefs.edit { putString(prop.name, v) }
        }
}

class Settings(prefs: SharedPreferences) {
    var username by PrefDelegateProvider(prefs, "guest") // key auto-derived as "username"
}

