import kotlin.properties.Delegates

// React after change
var name: String by Delegates.observable("Initial") {
    prop, old, new ->
    println("Changed from '$old' to '$new'")
}

name = "Alice"  // prints: Changed from 'Initial' to 'Alice'

// Reject invalid changes
var age: Int by Delegates.vetoable(0) {
    _, _, newValue -> newValue >= 0  // reject negative ages
}

age = 25   // ✅ accepted
age = -1   // ❌ rejected, age stays 25

interface Logger {
    fun log(message: String)
    fun error(message: String)
}

class ConsoleLogger : Logger {
    override fun log(message: String) = println("LOG: $message")
    override fun error(message: String) = println("ERR: $message")
}

// Delegates Logger to consoleLogger, overrides just one method
class TimestampLogger(
    consoleLogger: Logger
) : Logger by consoleLogger {
    override fun log(message: String) {
        println("[${System.currentTimeMillis()}] $message")
    }
    // error() is automatically delegated ✅
}

class LegacyConfig { var timeoutSeconds: Int = 30 }

class ModernConfig(legacy: LegacyConfig) {
    var timeoutMs: Int by legacy::timeoutSeconds // delegated alias — reads/writes forward directly
}

interface Logger { fun log(msg: String) }
interface Cache { fun get(key: String): String? }

class Service(
    logger: Logger,
    cache: Cache
) : Logger by logger, Cache by cache // delegates each interface to a different object
